$request=new WP_REST_Request('GET','/bench/v1/status'); wp_set_current_user(0); $r=rest_do_request($request); bench_check('anonymous_denied',$r->get_status()===401); $uid=wp_create_user('reader','fixture-only-password'); $u=new WP_User($uid); $u->set_role('subscriber'); wp_set_current_user($uid); bench_check('subscriber_denied',rest_do_request($request)->get_status()===403); wp_set_current_user(1); $r=rest_do_request($request); bench_check('admin_allowed',$r->get_status()===200 && $r->get_data()===['ready'=>true]);
